SELECT id, service, host, latency_ms, context, COALESCE(context['trace'], 'unknown') AS trace_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, ARRAY_CONTAINS(MAP_KEYS(context), 'trace') AS has_trace, SIZE(context) AS num_context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec FROM app_logs;
